local counts = {match = 0, DIFFERENT = 0, unreadable = 0, unknown = 0}
for _, s in ipairs(SIGS) do
  local group, name, base, rva, want = s[1], s[2], s[3], s[4], s[5]
  local verdict, seen
  if want == '' then verdict = 'unknown'
  else
    local got = rva and read(base + rva, #want / 2)
    seen = hex(got); verdict = not got and 'unreadable' or (seen == want and 'match' or 'DIFFERENT')
  end
  counts[verdict] = counts[verdict] + 1
  if verdict ~= 'match' then out('BLM_L0', group, name, rva and h(rva) or 'nil', verdict, verdict == 'DIFFERENT' and seen or '') end
end
out('BLM_L0 signatures: match', counts.match, 'DIFFERENT', counts.DIFFERENT, 'unreadable (not run yet)', counts.unreadable,
    'unknown (page dump needed)', counts.unknown, '(DIFFERENT must be 0)')
-- L1: ScriptApi tables (exe): lobby API +0xF8, package API +0x10, the slots the mod calls
local S = P(G + 0x2CE14C8)
out('BLM_L1 ScriptApi', S and h(S - X) or 'nil', 'expect 0x2870240')
if S then
  local lobby, pkg = P(S + 0xF8), P(S + 0x10)
  out('BLM_L1 lobby API', lobby and h(lobby - X) or 'nil', 'expect 0x28753B0', 'package API', pkg and h(pkg - X) or 'nil', 'expect 0x2871350')
  if lobby then out('BLM_L1 slot 0x40', h((P(lobby + 0x40) or X) - X), 'expect 0x948F50', 'slot 0x198', h((P(lobby + 0x198) or X) - X), 'expect 0x94A5C0') end
  if pkg then out('BLM_L1 slot 0x348', h((P(pkg + 0x348) or X) - X), 'expect 0x2F0BC0', 'slot 0x350', h((P(pkg + 0x350) or X) - X), 'expect 0x2F0BE0') end
end
-- the continent getter's object path (exe 0x948F50: [exe+0x2405AC8] -> +0xA8 -> +0x44 two-letter code, signed in)
local cont = P(X + 0x2405AC8)
local ce = cont and P(cont + 0xA8)
out('BLM_L1 continent object', h(cont), 'entry', h(ce), 'code', ce and cstr(ce + 0x44, 4) or 'nil', '(two letters, e.g. EU/NA, after sign-in)')
-- L2: game mode and the session
local GS = P(G + 0x2CE1508)
out('BLM_L2 game state', h(GS), 'mode +0xAC29C', U32(GS and GS + 0xAC29C), '(3 ship, 4 mission)', '| old +0xAC21C', U32(GS and GS + 0xAC21C))
local NC = P(G + 0x2E38228)
if NC then
  local count = U32(NC + 0x16390)
  out('BLM_L2 context', h(NC), 'local', H64(U64(NC + 0xB398)), 'host', H64(U64(NC + 0xB3A8)), 'peers +0x16390', count, '(1..4)')
  for i = 0, math.min(count or 0, 4) - 1 do
    out('BLM_L2 peer', i, H64(U64(NC + 0x16398 + 32 * i)), 'player index +20', U32(NC + 0x16398 + 32 * i + 20))
  end
  out('BLM_L2 host sync +0x159B0: hosting +24', U32(NC + 0x159B0 + 24), '(1 hosting)', 'step +28', U32(NC + 0x159B0 + 28), '(0)')
  out('BLM_L2 party join byte +0x162C8+0x529', U8(NC + 0x162C8 + 0x529), '(0)', '| old +0x521', U8(NC + 0x162C8 + 0x521))
  out('BLM_L2 join state +0x171D0', U32(NC + 0x171D0), '(0 idle)', '| old +0x171C8', U32(NC + 0x171C8))
  -- L4: lobby wrapper, PlayFab lobby, key cache, post countdown, browser handle
  local W = NC + 0x1D478
  local EL = P(W)
  local PF = EL and P(EL + 0x10)
  out('BLM_L4 engine lobby [NC+0x1D478]', h(EL), 'PlayfabLobby', h(PF), 'state +0x118', U32(PF and PF + 0x118), '(3 joined)',
      'members +0x100', U32(PF and PF + 0x100), 'handle +0x120', H64(U64(PF and PF + 0x120)), '| old [NC+0x1D470]', h(P(NC + 0x1D470)))
  out('BLM_L4 key cache: key 8 (SOS)', cstr(W + 56 + 257 * 8, 16), 'key 19 (privacy)', cstr(W + 56 + 257 * 19, 16),
      'pending bits +0x20', H64(U64(W + 0x20)), 'post countdown +0x1B80', F32(W + 0x1B80), '(0..30 s)')
  out('BLM_L4 browser handle [NC+0x1F030]', h(P(NC + 0x1F030)), '(nonzero after a lobby search)', '| old [NC+0x1F028]', h(P(NC + 0x1F028)))
  -- L7: text chat
  out('BLM_L7 chat enabled byte [NC+0xC418]', U8(NC + 0xC418), '(1 on)', 'history count +0x9594', U32(NC + 0xC418 + 0x9594), '(<= 64)')
else out('BLM_L2 no network context') end
-- L3: roster and the game's Text Language
local RO = P(G + 0x2E38210)
if RO then for i = 0, 3 do
  local lo, hi = U64(RO + 0xC0 * i)
  if lo and (lo ~= 0 or hi ~= 0) then out('BLM_L3 roster', i, H64(lo, hi), 'name', cstr(RO + 0xC0 * i + 8, 0x78)) end
end else out('BLM_L3 roster null') end
local li = U32(GS and GS + 705628 + 212)
local rec = li and li < 15 and P(G + 0x3180DE0 + 8 * li)
out('BLM_L3 language index', li, 'record', h(rec), 'code', rec and cstr(P(rec + 8), 8) or 'nil', "(e.g. 'us')")
-- L5: online config and the matchmaking scanner
local CFG = P(G + 0x2E38218)
out('BLM_L5 config', h(CFG), 'scanner recharge +0x3CEAC', I32(CFG and CFG + 0x3CEAC), '(20 from the server, or the mod setting 5..20)',
    'lobby post seconds +0x3CEC8', I32(CFG and CFG + 0x3CEC8), '(30)', '| old +0x3CE4C', I32(CFG and CFG + 0x3CE4C))
local MM = P(G + 0x2E381B8)
out('BLM_L5 matchmaking', h(MM), 'scanner countdown +0x10BD74', F32(MM and MM + 0x10BD74), '(N while "RECHARGING... N")',
    'quickplay state +0x68C', U32(MM and MM + 0x68C), 'scanner state +0x56E4', U32(MM and MM + 0x56E4))
-- L6: escape menu (open it on the GAME tab first)
local MS = P(G + 0x2E38170)
local SC = MS and P(MS + 0xC8)
out('BLM_L6 menu system', h(MS), 'escape screen [+0xC8]', h(SC), '(0 while closed)')
if SC then
  local C = SC + 281480
  local count = U8(C + 1789912)
  local types = {}
  for i = 0, math.min(count or 0, 5) - 1 do types[#types + 1] = U8(C + 1789913 + i) end
  out('BLM_L6 shown +8', U32(SC + 8), '(0 GAME)', 'buttons', count, 'types', table.concat(types, ','), '(game 0-4, mod 5-7)',
      'focus', U8(C + 1970000), 'dialog inactive', U8(C + 1989648), 'opening', U8(C + 1989649), 'fade', F32(C + 1989812),
      'panel', U32(C + 1832636), '(2 takes input)', 'hidden', U8(C + 1989808))
  for i = 0, math.min(count or 0, 5) - 1 do
    out('BLM_L6 button', i, 'label id', h(U32(C + 1714544 + 14920 * i + 1928 + 272)),
        '(game labels 42D7CF06 65E0947B 801EC7E7 1F6FF863 CC934148; mod C67C7FAF)')
  end
  for i = 0, 3 do
    local card = C + 1371024 + 85552 * i
    out('BLM_L6 card', i, 'peer', H64(U64(card + 85504)), 'state', U32(card + 85512), 'player menu', h(P(card + 7144)), 'KICK hold', F32(card + 85520))
  end
  out('BLM_L6 dialog state', U32(C + 1970288 + 19372), '(0 idle)', 'title label', h(U32(C + 1970288 + 1496 + 272)), 'body label', h(U32(C + 1970288 + 2192 + 272)))
end
local PR = P(G + 0x2E38160)
local MAIN = PR and P(PR + 0x4388)
out('BLM_L6 presenters', h(PR), 'Main presenter [+0x4388]', h(MAIN), '(nonzero while the escape menu is open)', 'pending close +16', U8(MAIN and MAIN + 16), '(0)')
-- L8: SOS (in a mission, as host)
local SOS = P(G + 0x2CE1DB0)
out('BLM_L8 SOS', h(SOS), 'on +8', U8(SOS and SOS + 8), 'beacons +24', U32(SOS and SOS + 24), 'privacy [GS+0xAC5D0]', U32(GS and GS + 0xAC5D0),
    '(0..3)', '| old [GS+0xAC550]', U32(GS and GS + 0xAC550))
-- L9: SOS Beacon stratagem (type 0x95) and your stratagem slots
local def, old = P(G + 0x31870E0 + 8 * 0x95), P(G + 0x31870E0 + 8 * 0x91)
out('BLM_L9 settings type 0x95', h(U32(def)), 'uses +0x50', I32(def and def + 0x50), '(1)', 'shared +0x94', U32(def and def + 0x94), '(0)',
    '| type 0x91 uses', I32(old and old + 0x50), '(-1, Orbital Confetti)')
local PL = P(G + 0x2E38188)
local own_lo, own_hi = U64(NC and NC + 0xB398)
if PL then
  local n = U32(PL + 0x2D800)
  out('BLM_L9 player records', h(PL), 'count +0x2D800', n, '(<= 32)', '| old +0x2D200', U32(PL + 0x2D200))
  for r = 0, math.min(n or 0, 32) - 1 do
    local rec = PL + 0x16C0 * r
    local lo, hi = U64(rec)
    if lo == own_lo and hi == own_hi then
      local slots = U32(rec + 0x7C0)
      out('BLM_L9 your record', r, 'slots +0x7C0', slots, '(<= 16)')
      for i = 0, math.min(slots or 0, 16) - 1 do
        local t = U32(rec + 0x1C0 + 48 * i)
        out('BLM_L9 slot', i, 'type', h(t), 'uses left', I32(rec + 0x1C0 + 48 * i + 4), t == 0x95 and '<- SOS Beacon (1 before use, 0 after)' or '')
      end
    end
  end
end
