local O = P(G + 0x2E38128)
if O then
  local T = O + 0xC050
  out('BLM_L10 OnlineOverrideData', h(P(T)), 'entries at +0x20', h(T + 0x20), 'capacity', U32(T + 8), '(512)', 'multiplier', U32(T + 16), '(2)',
      'count', U32(T + 24), 'checksum +0x6020', h(U32(T + 0x6020)), '| synced count', U32(O + 0x12078 + 24))
end
local ids = {}
for i = 0, 6 do ids[#ids + 1] = fmt('%08X', U32(G + 0x205D3F0 + 4 * i) or 0) end
out('BLM_L10 continent ids', table.concat(ids, ' '), '(9061BF63 C59A4447 617288E9 0FAB5B27 29CE1E3F CCC7BF91 D044AF30)')
return true

